    public static function svg(string $name, int $size = 16, string $class = '', ?string $label = null): string
    {
        $paths = self::PATHS[$name] ?? null;
        if ($paths === null) {
            return '';
        }
        $a11y = $label !== null && $label !== ''
            ? 'role="img" aria-label="' . htmlspecialchars($label, ENT_QUOTES) . '"'
            : 'aria-hidden="true" focusable="false"';
        return '<svg class="cn-icon' . ($class !== '' ? ' ' . htmlspecialchars($class, ENT_QUOTES) : '') . '" width="' . $size . '" height="' . $size
            . '" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" ' . $a11y . '>'
            . $paths . '</svg>';
    }

    /** @return list<string> */
    public static function names(): array
    {
        return array_keys(self::PATHS);
    }
